const titleCase = value => {
  const text = String(value || '').trim();
  return text ? `${text.charAt(0).toUpperCase()}${text.slice(1)}` : 'Unknown';
};

const boundedList = (values, fallback, limit = 5) => {
  const entries = (Array.isArray(values) ? values : [])
    .map(value => String(value || '').trim())
    .filter(Boolean);
  if (!entries.length) return fallback;
  const visible = entries.slice(0, limit);
  const remainder = entries.length - visible.length;
  return `${visible.join(', ')}${remainder > 0 ? `, +${remainder} more` : ''}`.slice(0, 160);
};

MODS.registerUiContribution('roster.here.badges', 'field-state', {
  label: 'Field state',
  description: 'A quick field-journal observation for this creature.',
  tone: 'info',
  priority: 0,
  read(context) {
    const unit = context.unit;
    const statuses = Array.isArray(unit?.statuses) ? unit.statuses : [];
    if (statuses.length) {
      return {
        label: statuses.length === 1 ? '1 condition' : `${statuses.length} conditions`,
        tone: 'warning'
      };
    }
    const disposition = String(unit?.disposition || '').trim().toLowerCase();
    if (disposition === 'enemy' || disposition === 'hostile') {
      return { label: 'Hostile', tone: 'danger' };
    }
    if (disposition === 'ally' || disposition === 'party' || disposition === 'friendly') {
      return { label: 'Friendly', tone: 'success' };
    }
    return { label: 'Observed', tone: 'info' };
  }
});

MODS.registerUiContribution('roster.details.sections', 'creature-notes', {
  label: 'Field journal',
  description: 'Bounded public details about this nearby creature.',
  priority: 0,
  when(context) {
    return context.unitType === 'creature' && Boolean(context.unit);
  },
  read(context) {
    const unit = context.unit;
    if (!unit) return { rows: [] };
    const punishment = unit.punishment || { current: 0, max: 0 };
    const spirit = unit.spirit || { current: 0, max: 0 };
    return {
      rows: [
        { label: 'Species', value: titleCase(unit.species) },
        { label: 'Disposition', value: titleCase(unit.disposition) },
        { label: 'Punishment', value: `${punishment.current} / ${punishment.max}` },
        { label: 'Spirit', value: `${spirit.current} / ${spirit.max}` },
        { label: 'Capabilities', value: boundedList(unit.capabilities, 'None observed') },
        { label: 'Conditions', value: boundedList(unit.statuses, 'None observed') }
      ]
    };
  }
});

MODS.registerUiContribution('system.utilities', 'current-summary', {
  label: 'Field journal',
  description: 'Summarize the current party and location from public information.',
  icon: '◇',
  tone: 'info',
  priority: 0,
  onInvoke() {
    const context = MODS.getContext({ limit: 1 });
    const location = context.location || { x: 0, y: 0, tile: null };
    const tile = location.tile || {};
    const party = Array.isArray(context.party) ? context.party : [];
    const partyNames = party.map(member => member?.name).filter(Boolean);
    const biome = tile.displayBiome || tile.biome || 'Uncharted';
    const danger = tile.dangerBand?.id || tile.danger || 'Unknown';
    return {
      title: 'Field journal',
      description: 'A quick field summary of the current location and traveling party.',
      rows: [
        { label: 'Coordinates', value: `${location.x}, ${location.y}` },
        { label: 'Terrain', value: titleCase(biome) },
        { label: 'Local danger', value: titleCase(danger) },
        { label: 'Party', value: `${party.length} ${party.length === 1 ? 'member' : 'members'}` },
        { label: 'Travelers', value: boundedList(partyNames, 'No party members', 4) },
        { label: 'Mode', value: titleCase(context.mode) }
      ]
    };
  }
});

MODS.log('Field Journal contributions registered.');
